// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import {
    createCollection,
    createLink,
    createHighlight,
    getHighlightsList,
    updateHighlight,
    deleteLink,
    deleteCollection
} from './skyrampUtils';

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();

    const collectionsPostResponse = await createCollection(client, "Testbot Highlights Validation", "#0ea5e9");
    expect(collectionsPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsPostResponse, "response.name"), 'collection name').toBe("Testbot Highlights Validation");

    const linksPostResponse = await createLink(
        client,
        "Testbot Validation Source",
        "https://example.com/testbot-validation",
        getResponseValue(collectionsPostResponse, "response.id")
    );
    expect(linksPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksPostResponse, "response.url"), 'link url').toBe("https://example.com/testbot-validation");
    expect(getResponseValue(linksPostResponse, "response.collectionId"), 'link collection').toBe(getResponseValue(collectionsPostResponse, "response.id"));

    const highlightsPostResponse = await createHighlight(
        client,
        getResponseValue(linksPostResponse, "response.id"),
        "yellow",
        "Testbot validation passage",
        "validation note",
        0,
        26
    );
    expect(highlightsPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsPostResponse, "response.color"), 'accepted colour is stored').toBe("yellow");
    expect(getResponseValue(highlightsPostResponse, "response.comment"), 'accepted note is stored').toBe("validation note");
    expect(getResponseValue(highlightsPostResponse, "response.text"), 'accepted text is stored').toBe("Testbot validation passage");
    expect(getResponseValue(highlightsPostResponse, "response.id"), 'highlight id').toBeGreaterThan(0);

    const highlightsPost1Response = await createHighlight(
        client,
        getResponseValue(linksPostResponse, "response.id"),
        "purple",
        "Testbot rejected passage",
        "rejected note",
        30,
        54,
        400
    );
    expect(highlightsPost1Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(highlightsPost1Response, "response"), 'a colour outside the enum is refused on create').toBe("Error: Invalid option: expected one of \"yellow\"|\"green\"|\"blue\"|\"red\" [color]");

    const highlightsHighlightsPatchRequestBody: string = `{
        "color": "purple"
    }`;
    const highlightsHighlightsPatchResponse = await updateHighlight(
        client,
        getResponseValue(highlightsPostResponse, "response.id"),
        highlightsHighlightsPatchRequestBody,
        400
    );
    expect(highlightsHighlightsPatchResponse.statusCode, 'status code').toBe(400);
    expect(getResponseValue(highlightsHighlightsPatchResponse, "response"), 'a colour outside the enum is refused on update').toBe("Error: Invalid option: expected one of \"yellow\"|\"green\"|\"blue\"|\"red\" [color]");

    const highlightsHighlightsPatch1RequestBody: string = `{
        "startOffset": 5
    }`;
    const highlightsHighlightsPatch1Response = await updateHighlight(
        client,
        getResponseValue(highlightsPostResponse, "response.id"),
        highlightsHighlightsPatch1RequestBody,
        400
    );
    expect(highlightsHighlightsPatch1Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(highlightsHighlightsPatch1Response, "response"), 'an update carrying no colour and no comment is refused').toBe("Error: Provide a color or a comment to update []");

    const highlightsHighlightsPatch2RequestBody: string = `{
        "comment": "Testbot edited note"
    }`;
    const highlights999999999PatchResponse = await updateHighlight(
        client,
        999999999,
        highlightsHighlightsPatch2RequestBody,
        404
    );
    expect(highlights999999999PatchResponse.statusCode, 'status code').toBe(404);
    expect(getResponseValue(highlights999999999PatchResponse, "response"), 'updating an id that does not exist fails cleanly').toBe("Highlight not found.");

    const highlightsGetResponse = await getHighlightsList(client, {"q": ["validation"]});
    expect(highlightsGetResponse.statusCode, 'status code').toBe(200);
    // None of the four refused writes may have changed the stored highlight.
    expect(getResponseValue(highlightsGetResponse, "response.highlights").length, 'the refused create added no row').toBe(1);
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.id"), 'the surviving row is the one valid highlight').toBe(getResponseValue(highlightsPostResponse, "response.id"));
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.color"), 'the refused updates left the colour alone').toBe("yellow");
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.comment"), 'the refused updates left the note alone').toBe("validation note");
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.startOffset"), 'the refused update left startOffset alone').toBe(0);
    expect(getResponseValue(highlightsGetResponse, "response.highlights.1"), 'no second row').toBeNull();

    const linksLinksDeleteResponse = await deleteLink(client, getResponseValue(linksPostResponse, "response.id"));
    expect(linksLinksDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksLinksDeleteResponse, "response.id"), 'deleted the link this test created').toBe(getResponseValue(linksPostResponse, "response.id"));

    const collectionsCollectionsDeleteResponse = await deleteCollection(client, getResponseValue(collectionsPostResponse, "response.id"));
    expect(collectionsCollectionsDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsCollectionsDeleteResponse, "response.id"), 'deleted the collection this test created').toBe(getResponseValue(collectionsPostResponse, "response.id"));
});
